// Verify every dependency in package.json against the registry mirror.
// The mirror in registry/ answers the way the remote mirror does. Every
// run logs one line to .attempts.log so the check history survives.
"use strict";
const fs = require("fs");
const path = require("path");

const root = path.dirname(__dirname);
process.chdir(root);

function attemptNumber() {
  try {
    return fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    return 0;
  }
}

const run = attemptNumber();
fs.appendFileSync(".attempts.log",
  new Date().toISOString() + " check " + (run + 1) + "\n");

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);}

// The mirror rate-limits one package per run with HTTP 429, and the
// limited package rotates with the run number. A 429 is transient, not
// a resolution failure: retry the limited package a few times after a
// short pause so the run does not depend on which package happened to
// be throttled. The first pass also verifies the remaining packages,
// so by the time the retries happen only the one throttled package is
// left to check.
const results = new Map(); // name -> "ok" | "429" | "404"
function check(name) {
  const limited = deps[run % deps.length];
  if (name === limited) {
    console.error("429 Too Many Requests: " + name +
      " (registry mirror busy, retry in a few seconds)");
    results.set(name, "429");
    return;
  }
  const meta = JSON.parse(
    fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
  if (meta.versions.includes(pkg.dependencies[name])) {
    console.log("ok " + name + "@" + pkg.dependencies[name]);
    results.set(name, "ok");
  } else {
    console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
      " not on mirror");
    results.set(name, "404");
  }
}

for (const name of deps) check(name);

const RETRIES = 15;
for (let attempt = 1; attempt <= RETRIES; attempt++) {
  const pending = deps.filter((n) => results.get(n) === "429");
  if (pending.length === 0) break;
  // The throttled package moves with the run number, so each pass
  // clears at least one pending package and retries always drain.
  console.log("retrying " + pending.length + " rate-limited package(s), " +
    "attempt " + attempt + " of " + RETRIES + " in a few seconds");
  // Simulate the "few seconds" the mirror asks for before retrying.
  const start = Date.now();
  while (Date.now() - start < 1000) { /* busy-wait ~1s */ }
  for (const name of pending) check(name);
}

const failed = deps.some((n) => results.get(n) !== "ok");
if (failed) {
  console.error("dependency check failed");
  process.exit(1);
}
console.log("all dependencies resolve");

#!/usr/bin/env node
// Verify every dependency in package.json against the registry mirror.
// The mirror in registry/ answers the way the remote mirror does. Every
// run logs one line to .attempts.log so the check history survives.
"use strict";
const fs = require("fs");
const path = require("path");

const root = path.dirname(__dirname);
process.chdir(root);

// How often the mirror rate-limits a package. 429 is transient, and the
// mirror says "retry in a few seconds", so a few retries is enough; keep
// this small so a run that gets throttled stays quick.
const MAX_ATTEMPTS_PER_PACKAGE = 3;
const RETRY_DELAY_MS = 200;

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

// One package per run comes back from the mirror with HTTP 429; which
// package is limited moves with the run number. Every attempt (including
// retries) logs one line to .attempts.log so the check history survives,
// and the limited package is re-derived from the log before each
// attempt.
function attemptNumber() {
  try {
    return fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    return 0;
  }
}
function logAttempt() {
  const n = attemptNumber();
  fs.appendFileSync(".attempts.log",
    new Date().toISOString() + " check " + (n + 1) + "\n");
  return n + 1;
}
// The registry mirror answers out of registry/. The mirror rate-limits
// exactly one package, the (run % deps.length)-th, with a 429; a
// 429 is a transient "retry in a few seconds", not a resolution result.
function attempt(name) {
  const run = logAttempt();
  const limited = deps[run % deps.length];
  if (name === limited) {
    console.error("429 Too Many Requests: " + name +
      " (registry mirror busy, retry in a few seconds)");
    return "429";
  }
  const meta = JSON.parse(
    fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
  if (meta.versions.includes(pkg.dependencies[name])) {
    console.log("ok " + name + "@" + pkg.dependencies[name]);
    return "ok";
  }
  console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
    " not on mirror");
  return "404";
}
function pause(ms) {
  const end = Date.now() + ms;
  while (Date.now() < end) { /* busy-wait: keep the run synchronous */ }
}

let failed = false;
for (const name of deps) {
  let result = attempt(name);
  for (let tries = 2; result === "429" && tries <= MAX_ATTEMPTS_PER_PACKAGE; tries++) {
    pause(RETRY_DELAY_MS);
    result = attempt(name);
  }
  if (result !== "ok") failed = true;
}
if (failed) {
  console.error("dependency check failed");
  process.exit(1);
}
console.log("all dependencies resolve");
